import java.util.Scanner;

public class Main {
    static final int MAX_SIZE = 100000 + 100000; // 2 * 10^5, adjusted for safety
    static final long MOD_CONST = 1000000007L;

    static long base, modulus;
    static int total;
    static long result;
    static boolean[] visited = new boolean[MAX_SIZE];
    static int[] values = new int[MAX_SIZE];

    static void normalize(long[] x) {
        x[0] = ((x[0] % MOD_CONST) + MOD_CONST) % MOD_CONST;
    }

    static void explore(int x) {
        total++;
        int initial = x;
        long weight = 1;
        do {
            visited[x] = true;
            x = (int)((x * base) % modulus);
            weight = (weight * base) % modulus;
        } while (x != initial);
        long[] resArr = {result};
        normalize(resArr);
        result = resArr[0] * (weight == 1 ? modulus : 1);
        normalize(resArr);
        result = resArr[0];
    }

    static void compute() {
        if (base == 0) {
            long prod = 1;
            for (int i = 1; i <= modulus - 1; i++) {
                prod = (prod * modulus) % MOD_CONST;
            }
            System.out.println(prod);
            return;
        }
        result = 1;
        for (int i = 0; i <= modulus - 1; i++) {
            if (!visited[i]) {
                explore(i);
            }
        }
        System.out.println(result);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        // Read input
        modulus = sc.nextLong();
        base = sc.nextLong();

        compute();

        sc.close();
